 IF EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='referral_campaign') AND NOT ((SELECT COUNT(*) FROM (SELECT COLUMN_NAME,ORDINAL_POSITION,COLUMN_DEFAULT,IS_NULLABLE,DATA_TYPE,COLUMN_TYPE,CHARACTER_SET_NAME,COLLATION_NAME,EXTRA,IS_GENERATED,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='referral_campaign') hb_rows)=7 AND NOT EXISTS(SELECT 1 FROM (SELECT COLUMN_NAME,ORDINAL_POSITION,COLUMN_DEFAULT,IS_NULLABLE,DATA_TYPE,COLUMN_TYPE,CHARACTER_SET_NAME,COLLATION_NAME,EXTRA,IS_GENERATED,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='referral_campaign') hb_rows WHERE NOT ((BINARY `COLUMN_NAME` <=> BINARY 'id' AND `ORDINAL_POSITION`=1 AND `COLUMN_DEFAULT` IS NULL AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'varchar' AND BINARY `COLUMN_TYPE` <=> BINARY 'varchar(32)' AND BINARY `CHARACTER_SET_NAME` <=> BINARY 'utf8mb4' AND BINARY `COLLATION_NAME` <=> BINARY 'utf8mb4_unicode_ci' AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL) OR (BINARY `COLUMN_NAME` <=> BINARY 'enabled' AND `ORDINAL_POSITION`=2 AND BINARY `COLUMN_DEFAULT` <=> BINARY '1' AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'bigint' AND BINARY `COLUMN_TYPE` <=> BINARY 'bigint(20)' AND `CHARACTER_SET_NAME` IS NULL AND `COLLATION_NAME` IS NULL AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENERATION_EXPRESSION` IS NULL) OR (BINARY `COLUMN_NAME` <=> BINARY 'friend_discount_paisa' AND `ORDINAL_POSITION`=3 AND `COLUMN_DEFAULT` IS NULL AND BINARY `IS_NULLABLE` <=> BINARY 'NO' AND BINARY `DATA_TYPE` <=> BINARY 'bigint' AND BINARY `COLUMN_TYPE` <=> BINARY 'bigint(20)' AND `CHARACTER_SET_NAME` IS NULL AND `COLLATION_NAME` IS NULL AND BINARY `EXTRA` <=> BINARY '' AND BINARY `IS_GENERATED` <=> BINARY 'NEVER' AND `GENE